async function dispatchRequest(
  req: http.IncomingMessage,
  res: http.ServerResponse,
  pathname: string
): Promise<void> {
  const routeHandler = resolveRoute(ROUTES, req.method!, pathname);
  if (routeHandler) {
    try {
      await routeHandler(req, res);
    } catch (err) {
      handleRouteError(err, res);
    }
    return;

export function handleRouteError(
  err: Error & { errorCode?: string; status?: number },
  res: ServerResponse
): void {
  if (!res.headersSent) {
    const code = err.errorCode || statusToCode(err.status || 500);
    json(res, err.status || 500, errorResponse(code, err.message));
  } else {
    res.end();
  }
}

