  // Atomic write: temp-file-then-rename (IMPL-CONSTRAINT-007)
  const tmpPath = filePath + '.tmp.' + process.pid + '.' + Date.now();
  try {
    fs.writeFileSync(tmpPath, data, (encoding || 'utf8') as BufferEncoding);
    fs.renameSync(tmpPath, filePath);

