pub(crate) fn run_cleanup(
    conn: &Connection,
    media_mgr: &MediaManager,
    retention_days: i64,
) -> Result<CleanupStats> {
    if retention_days <= 0 {
        return Ok(CleanupStats::default());
    }

    let now_millis = chrono::Utc::now().timestamp_millis();
    let cutoff = now_millis - retention_days * 86_400 * 1000;

