def _build_params(fn: Callable[..., Any], args: tuple, kwargs: dict) -> dict[str, Any]:
    """
    Map positional and keyword arguments to a parameter dict,
    using the function's signature (excluding 'self').
    """
    sig = inspect.signature(fn)
    param_names = [
        name for name, p in sig.parameters.items()
        if name != "self" and p.kind not in (
            inspect.Parameter.VAR_POSITIONAL,
            inspect.Parameter.VAR_KEYWORD,
        )
    ]

    params: dict[str, Any] = {}
    for i, value in enumerate(args):
        if i < len(param_names):
            params[param_names[i]] = value
    params.update(kwargs)
    return params

def _redact_meta(meta: dict[str, Any]) -> dict[str, Any]:
    """
    Return a copy of meta with sensitive keys redacted to '[REDACTED]'.
    Case-insensitive matching against common secret key names.
    """
    if not meta:
        return {}
    redacted = {}
    for key, value in meta.items():
        if key.lower() in _SENSITIVE_KEYS:
            redacted[key] = "[REDACTED]"
        else:
            redacted[key] = value
    return redacted

